package coverage_test

import (
	"reflect"
	"strings"
	"testing"

	"github.com/cristianargotti/golaw/internal/coverage"
)

func migratedRoot(t *testing.T) string {
	t.Helper()
	root := t.TempDir()
	for name, content := range map[string]string{
		"go.mod":      "module " + moduleName + "\n\ngo 1.27\n",
		"a/a.go":      "package a\nfunc A() int { return 1 }\n",
		"a/a_test.go": "package a\n",
		"a/generated.go": "// Code generated by fixture. DO NOT EDIT.\n" +
			"package a\nfunc Generated() int { return 1 }\n",
		"a/types.go":      "package a\ntype T struct{}\n",
		"a/literal.go":    "package a\nvar Literal = func() int { return 1 }\n",
		"vendor/v/v.go":   "package v\nfunc V() int { return 1 }\n",
		"a/testdata/x.go": "package x\nfunc X() int { return 1 }\n",
	} {
		writeCoverageFile(t, root, name, content)
	}
	return root
}

func migratedProfile() string {
	return "mode: atomic\n" +
		moduleName + "/a/a.go:2.14,2.28 1 1\n" +
		moduleName + "/a/literal.go:2.26,2.40 1 1\n" +
		moduleName + "/a/generated.go:3.22,3.36 1 0\n" +
		moduleName + "/vendor/v/v.go:2.14,2.28 1 0\n"
}

func TestGeneratedProfileEntriesDoNotContaminateCoverage(t *testing.T) {
	t.Parallel()
	report, err := coverage.Evaluate(
		strings.NewReader(migratedProfile()), migratedRoot(t),
		coverage.DefaultFloors(),
	)
	if err != nil || len(report.Failures) != 0 ||
		report.Total.Statements != 2 || report.Total.Covered != 2 {
		t.Fatalf("report = %+v, error = %v", report, err)
	}
	names := make([]string, 0, len(report.Files))
	for _, file := range report.Files {
		names = append(names, file.Name)
	}
	if !reflect.DeepEqual(names, []string{"a/a.go", "a/literal.go"}) ||
		len(report.Skipped) != 3 {
		t.Fatalf("units = %+v", report)
	}
}

func TestMissingSourceFailsAtEitherMinimum(t *testing.T) {
	t.Parallel()
	for _, tc := range []struct {
		name    string
		minimum int
	}{
		{"one-statement", 1},
		{"twenty-statements", 20},
	} {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			root := migratedRoot(t)
			content := "package b\nfunc B() int {\n\tx := 0\n" +
				strings.Repeat("\tx++\n", 20) + "\treturn x\n}\n"
			writeCoverageFile(t, root, "b/b.go", content)
			floors := coverage.DefaultFloors()
			floors.MinStatements = tc.minimum
			report, err := coverage.Evaluate(
				strings.NewReader(migratedProfile()), root, floors,
			)
			if err != nil || len(report.Failures) != 1 ||
				report.Failures[0].Name != "b/b.go" ||
				report.Total.Statements != 2 {
				t.Fatalf("report = %+v, error = %v", report, err)
			}
		})
	}
}

func TestEachFloorHasItsOwnThreshold(t *testing.T) {
	t.Parallel()
	for _, tc := range []struct {
		name   string
		floors coverage.Floors
		want   []string
	}{
		{"near-all", coverage.DefaultFloors(), nil},
		{"red-total", coverage.Floors{Total: 94, Package: 80, File: 80, MinStatements: 20}, []string{"total"}},
		{"red-package", coverage.Floors{Total: 80, Package: 91, File: 80, MinStatements: 20}, []string{moduleName + "/p"}},
		{"red-file", coverage.Floors{Total: 80, Package: 80, File: 81, MinStatements: 20}, []string{"p/low.go"}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			root := t.TempDir()
			writeCoverageFile(t, root, "go.mod", "module "+moduleName+"\n\ngo 1.27\n")
			for name, signature := range map[string]string{
				"p/high.go": "package p\nfunc High() int",
				"p/low.go":  "package p\nfunc Low() int",
				"q/full.go": "package q\nfunc Full() int",
			} {
				source := signature + " {\n\tx := 0\n" +
					strings.Repeat("\tx++\n", 18) + "\treturn x\n}\n"
				writeCoverageFile(t, root, name, source)
			}
			profile := "mode: atomic\n" +
				moduleName + "/p/high.go:3.2,22.10 20 1\n" +
				moduleName + "/p/low.go:3.2,18.5 16 1\n" +
				moduleName + "/p/low.go:19.2,22.10 4 0\n" +
				moduleName + "/q/full.go:3.2,22.10 20 1\n"
			report, err := coverage.Evaluate(strings.NewReader(profile), root, tc.floors)
			if err != nil {
				t.Fatal(err)
			}
			var failures []string //nolint:prealloc // no failure stays nil, as the near-all row spells it
			for _, failure := range report.Failures {
				failures = append(failures, failure.Name)
			}
			if !reflect.DeepEqual(failures, tc.want) {
				t.Fatalf("failures = %v", failures)
			}
		})
	}
}

func TestSourceFailuresDoNotAnswerClean(t *testing.T) {
	t.Parallel()
	for _, broken := range []bool{false, true} {
		root := t.TempDir()
		if broken {
			root = migratedRoot(t)
			writeCoverageFile(t, root, "broken/b.go", "package b\nfunc {\n")
		}
		_, err := coverage.Evaluate(
			strings.NewReader(migratedProfile()), root,
			coverage.DefaultFloors(),
		)
		if err == nil {
			t.Fatal("incomplete measurement answered clean")
		}
	}
}
